#!/usr/bin/env node
'use strict';
/**
 * Writes the IPTC Digital Source Type "trainedAlgorithmicMedia" into every AI illustration's
 * .jpg and .webp, as XMP, so the files themselves say how they were made wherever they are
 * copied. Google reads this field (Search Central, "Image metadata in Google Images"); the page
 * already says "Illustration, generated by AI" underneath each one.
 *
 * Nothing is re-encoded: an XMP packet is inserted as a JPEG APP1 segment, and as a WebP "XMP "
 * chunk (adding the VP8X header a plain WebP lacks). Running it twice changes nothing.
 *
 *   node tools/mark-illustrations.js           mark every illustration that is not yet marked
 *   node tools/mark-illustrations.js --check   exit 1 if any illustration is unmarked
 */
const fs = require('fs');
const path = require('path');
const { isDrawn } = require('../src/lib/image-inventory');

/* The source copies; the build copies them to assets/img/recipes. --check reads the served ones. */
const SRC_DIR = path.join(__dirname, '..', 'src', 'assets', 'img', 'recipes');
const OUT_DIR = path.join(__dirname, '..', 'assets', 'img', 'recipes');
const TYPE = 'http://cv.iptc.org/newscodes/digitalsourcetype/trainedAlgorithmicMedia';
const xmlEsc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

function packet(title) {
  return `<?xpacket begin="﻿" id="W5M0MpCehiHzreSzNTczkc9d"?>
<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">
<rdf:Description rdf:about="" xmlns:Iptc4xmpExt="http://iptc.org/std/Iptc4xmpExt/2008-02-29/" xmlns:dc="http://purl.org/dc/elements/1.1/"
 Iptc4xmpExt:DigitalSourceType="${TYPE}">
<dc:description><rdf:Alt><rdf:li xml:lang="x-default">${xmlEsc(`AI-generated illustration of ${title}; not a photograph of the dish.`)}</rdf:li></rdf:Alt></dc:description>
</rdf:Description></rdf:RDF></x:xmpmeta>
<?xpacket end="w"?>`;
}

const marked = buf => buf.includes(Buffer.from('trainedAlgorithmicMedia'));

function markJpeg(buf, xmp) {
  if (buf[0] !== 0xff || buf[1] !== 0xd8) throw new Error('not a JPEG');
  const body = Buffer.concat([Buffer.from('http://ns.adobe.com/xap/1.0/\0', 'latin1'), Buffer.from(xmp, 'utf8')]);
  if (body.length + 2 > 0xffff) throw new Error('XMP too long');
  const seg = Buffer.alloc(4); seg[0] = 0xff; seg[1] = 0xe1; seg.writeUInt16BE(body.length + 2, 2);
  /* After SOI and any APP0 (JFIF), which must stay first. */
  let at = 2;
  if (buf[2] === 0xff && buf[3] === 0xe0) at = 4 + buf.readUInt16BE(4);
  return Buffer.concat([buf.slice(0, at), seg, body, buf.slice(at)]);
}

function chunk(fourcc, data) {
  const head = Buffer.alloc(8); head.write(fourcc, 0, 'latin1'); head.writeUInt32LE(data.length, 4);
  return Buffer.concat([head, data, data.length % 2 ? Buffer.alloc(1) : Buffer.alloc(0)]);
}

/** Width and height of a simple WebP's first frame (VP8 or VP8L). */
function webpSize(buf) {
  const kind = buf.toString('latin1', 12, 16);
  if (kind === 'VP8 ') return { w: buf.readUInt16LE(26) & 0x3fff, h: buf.readUInt16LE(28) & 0x3fff };
  if (kind === 'VP8L') {
    const b = buf.readUInt32LE(21);
    return { w: (b & 0x3fff) + 1, h: ((b >> 14) & 0x3fff) + 1 };
  }
  throw new Error(`unexpected WebP chunk ${kind}`);
}

function markWebp(buf, xmp) {
  if (buf.toString('latin1', 0, 4) !== 'RIFF' || buf.toString('latin1', 8, 12) !== 'WEBP') throw new Error('not a WebP');
  let chunks = buf.slice(12);
  if (buf.toString('latin1', 12, 16) === 'VP8X') {
    chunks = Buffer.from(chunks);
    chunks[8] |= 0x04;                                   // XMP present
  } else {
    const { w, h } = webpSize(buf);
    const x = Buffer.alloc(10);
    x[0] = 0x04;                                         // flags: XMP
    x.writeUIntLE(w - 1, 4, 3); x.writeUIntLE(h - 1, 7, 3);
    chunks = Buffer.concat([chunk('VP8X', x), chunks]);
  }
  const body = Buffer.concat([chunks, chunk('XMP ', Buffer.from(xmp, 'utf8'))]);
  const head = Buffer.alloc(12); head.write('RIFF', 0, 'latin1'); head.writeUInt32LE(body.length + 4, 4); head.write('WEBP', 8, 'latin1');
  return Buffer.concat([head, body]);
}

function main() {
  const check = process.argv.includes('--check');
  const images = require('../src/data/images.json');
  const titles = Object.fromEntries(require('../src/data/volumes').catalog().map(r => [r.slug, r.title]));
  let done = 0; let already = 0; const missing = [];
  for (const [slug, entry] of Object.entries(images)) {
    for (const shot of [entry && entry.hero, entry && entry.process]) {
      if (!shot || !isDrawn(shot)) continue;
      for (const ext of ['jpg', 'webp']) {
        const file = path.join(check ? OUT_DIR : SRC_DIR, `${shot.file}.${ext}`);
        if (!fs.existsSync(file)) continue;
        const buf = fs.readFileSync(file);
        if (marked(buf)) { already++; continue; }
        if (check) { missing.push(`${shot.file}.${ext}`); continue; }
        const xmp = packet(titles[slug] || shot.title || slug);
        fs.writeFileSync(file, ext === 'jpg' ? markJpeg(buf, xmp) : markWebp(buf, xmp));
        done++;
      }
    }
  }
  if (check) {
    for (const m of missing) console.log(`  ✗ ${m} does not carry the IPTC trainedAlgorithmicMedia source type`);
    if (!missing.length) console.log(`  ✓ all ${already} illustration files carry the IPTC trainedAlgorithmicMedia source type`);
    process.exit(missing.length ? 1 : 0);
  }
  console.log(`${done} files marked, ${already} already marked`);
}

if (require.main === module) main();
module.exports = { markJpeg, markWebp, packet };
